        "さて、それではオリエントの文明の地形的な特徴をあげておこう。",
        "メソポタミアは周囲がほとんど陸続きだから、さまざまな民族が外から攻めてくることが多かった。東のザグロス山脈は、一番高いところが約5000mもあるんだけど、山から下りてくる民族もいてね。さまざまな民族が入ってきていろいろな国を建てた。教科書的に言うと「開放的な地形」だ。これに対してエジプトは、周囲を海と砂漠、密林に囲まれているから、こちらは「閉鎖的な地形」。この時代にはまた、航海術があまり発達していなかったから、海から攻め込まれることは少なかったんだ。だからエジプトはずっとエジプト人の王朝が続くよ。",
