        "ティグリス川・ユーフラテス川に挟まれた地域は「肥沃な三日月地帯」って呼ばれている農耕に適した地域だよ。4月から6月にかけて雪解けで起こる増水を利用した灌漑によって農耕が発達し、前3500年ころから人口が急激に増え始めて、神殿を中心とする大集落がつくられていった。そして文字が発明され、青銅器などが普及し始めると、さらに農業生産力が向上して、神官・商人・職人などの農業をしない人たちが増え、農耕集落は都市へと発展していったんだよ。こうして前3000年ころには、民族系統不明のシュメール人によってウル・ウルク・ラガシュなどの都市国家が建設されたんだね。シュメール人の都市は城壁で囲まれていて、内部には壮大な神殿・宮殿・王墓が建てられたよ。"
