      "id": "mesopotamia-004",
      "title": "初めてメソポタミアを統一したのは？",
      "body": [
        "シュメール人の都市が衰退し始めると、シリアやアラビア半島から現れたセム語系の民族が台頭し始めた。セム語系民族は、メソポタミア文明の初期からすでに定着した、おもに遊牧生活をおこなっていた民族だね。そして、前24世紀ごろ、中部から興ったアッカド人の王サルゴン1世がメソポタミア全域の征服に成功した。これがメソポタミア最初の統一国家だね。しかし、この国もザグロス山脈から下りてきた山地の遊牧民（グティ人）の侵入で衰退し、ウル第3王朝の下で再びシュメール人の勢力が復興したよ。この王朝の創始者ウルナンムが発布した法典は、現存最古の法典といわれているね。しかし、この国も周辺の遊牧民の侵入で衰え、前3000年紀末にエラム人の侵入で滅んでしまったんだ。ね、メソポタミアっていろんな民族が次から次へと入ってきて、次々と国がかわるよね。"
      ],
