      "id": "mesopotamia-006",
      "title": "ハンムラビ王の登場。バビロン第1王朝がメソポタミア統一だ！",
      "body": [
        "ハンムラビは、大規模な治水や灌漑をおこなうとともに、有名なハンムラビ法典を制定した。これは領内のさまざまな民族を統一して支配するために、これまであったシュメール法を集大成したものだよ（だから最古の法典じゃない！）。全282条からなるこの法典は、刑法・商法・民法と内容は幅広く、特に刑法では「目には目を、歯には歯を」で有名な同害復讐の原則がとられている。これは、被害者がやられたのと同じことを国がかわりに刑罰としてやってあげる、ってことね。被害者本人がやり返したらただの犯罪だよ。それから、刑罰は被害者の身分によって異なり（身分法）、例えば、奴隷を殺しちゃった場合は、銀で賠償すればよかったんだ。"
      ],
