      "title": "インド＝ヨーロッパ語系民族が侵入してきた！",
      "body": [
        "前2000年ころから、オリエント文明は大きな変化を迎える。それは、インド＝ヨーロッパ語系民族の出現だ。彼らは単一の人種というよりは、中央アジアから南ロシアを原住地とするさまざまな民族だったみたいだね。ただ、彼らは共通の要素を持った言語を使用していたので、まとめてインド＝ヨーロッパ語系と呼ばれている。もう一つ、彼らの共通点は「馬と戦車」を使用したことだよ。機動力のある軍隊で各地に拡大していったんだね。西方に拡大したケルト人やイタリア人、南方に進出したギリシア人、さらには東方に進出したイラン人やインドに侵入したアーリア人も、インド＝ヨーロッパ語系民族だ。",
        "オリエント世界でも、アナトリア（小アジア）からメソポタミアへと拡大し、インド＝ヨーロッパ語系民族の征服国家が建設されたよ。こうして、オリエントはエジプトも含めて各地方が何らかのつながりを持ち、一つのまとまった世界が形成されていったんだ。では、彼らの国家形成を見ていこう。"
      ],
