      "id": "ancient-egypt-004",
      "title": "中王国時代――末期には、異民族ヒクソスが攻めてきた！",
      "body": [
        "前21世紀になると、上エジプトのテーベを中心に再びエジプトが統一された。これが中王国時代（第11〜12王朝）だ。テーベって海からだと直線距離で約800kmも内陸だから、エジプトでは最も安定した地域だよ。以後、長期にわたってテーベがエジプトの政治・宗教の中心になり、この時代には官僚機構が整備されて中央集権体制が整えられたんだ。",
        "それから、中王国時代にはテーベの守護神アメン【アモン】が多神教の最高神とされ、のちの新王国時代になると、もともと最高神だった太陽神ラーと結びついてアメン＝ラーとして広く信仰されるようになる。しかし、徐々に地方勢力と神官の勢力拡大で王権が衰退、統一が崩れてしまったんだ。ここからが第2中間期だよ。"
      ],
