      "id": "ancient-egypt-006",
      "title": "新王国時代①――いよいよエジプトも対外進出だ！",
      "body": [
        "まずは前15世紀のトトメス3世ね。彼は「エジプト最大の王」といわれ、シリアやナイル川上流のヌビアを征服して、古代エジプトの最大領域を実現したよ。こんなにすごいファラオだったんだけど……エジプトには大問題が発生。それは「神」の問題なんだ。",
        "古代エジプトでは、ファラオは太陽神ラーの子ということになっていて、閉鎖的なエジプトでは、ずっと神権政治がおこなわれていたよね。新王国時代は対外遠征が盛んで戦争の前後に必ず神殿での儀式がおこなわれたから、戦いに勝つと「やはり神の力はすごい！」ってことになっちゃう。そしてトトメス3世の時代には……エジプトはむちゃくちゃ強かった！ってことは「神がむちゃくちゃ強い！」ってことになるんだ。",
        "じゃあ、神が強いってなんだろう？　それって……要するに神殿に仕える神官が強いってことだよ。だって、神の言葉を伝えるのは、結局は神官だもん。しかし、神官たちがだんだんと政治に口出しするようになってきた。この状況を打破しようとしたのが、前14世紀のアメンヘテプ4世【アメンホテプ4世】だ！"
      ],
