      "id": "ancient-egypt-008",
      "title": "新王国時代②――神を変えちゃったアメンヘテプ4世",
      "body": [
        "しかし、この宗教改革には反発も強かった。テーベの神官たちも黙って見ていたわけではなく「いつか逆襲してやる」って思っていた。だから、アクエンアテンの死によって、この宗教改革は終わり、後継者のツタンカーメンはアメン神官団に屈してメンフィスに都を還し、従来の多神教信仰に戻したんだね。",
        "ちなみにツタンカーメンは、未盗掘の王墓に残された秘宝と呪いで有名な、あの国王だよ。それから、アメンヘテプ4世の時代は有名だから、エジプトが強かった時代というイメージかもしれないけど、実はエジプトが分裂して、下エジプトの支配がゆるみ、シリアから後退した時代なんだ。ここから反撃して、エジプトに再度の繁栄をもたらしたのが、第19王朝の王ラメス2世【ラメセス2世】だ。"
      ],
