      "id": "levant-peoples-007",
      "title": "さらなる苦難のなかからユダヤ教が生まれた！",
      "body": [
        "このときユダヤ人たちは「なんで自分たちだけが次々とひどい目にあうんだろう？」って考えた。そこで一つの結論に達するんだ。「出エジプト」「バビロン捕囚」と重なる民族的受難は、きっと神様が自分たちだけを救ってくれるために試練を与えているんだ、今はテストされてるに違いない！って。だからこの受難の時でも神を信仰し続ければ、きっと自分たちだけを救ってくれるに違いない、って考えて神への信仰を強めていった。そして、本当に救世主がきた。とはいってもアケメネス朝ペルシアのキュロス2世が、新バビロニアを滅ぼしたってことだけど。これでバビロン捕囚から解放されたユダヤ人は、イェルサレムに戻りヤハウェ神殿を再建した。これがユダヤ教の成立だ。あっ、ヘブライ人はこの時期から、旧ユダ王国の民って意味で「ユダヤ人」って呼ばれるようになるよ。"
      ],
