      "id": "levant-peoples-008",
      "title": "さらなる苦難のなかからユダヤ教が生まれた！",
      "body": [
        "ユダヤ教が持っている、ユダヤ人だけが救われるっていう選民思想や、神によってメシア（救世主）が遣わされる、っていう信仰はこうして形成されたんだね。そして、神に救ってもらえるようにするには、神との契約を厳格に守っていくことが必要だ、って考えた（戒律主義）。これらの思想をまとめたのが、聖典の「旧約聖書」だ。唯一神ヤハウェによる天地創造に始まって、これまでのヘブライ人の苦難の歴史も、この「旧約聖書」に記されているよ。ただ、「自分たちだけが救われる」っていうこの信仰は、彼らをさらに苦難に巻き込みそうな予感がするね。"
      ],
