      "id": "assyria-001",
      "title": "強大な軍事国家アッシリアの登場！",
      "body": [
        "それじゃあ、頭のなかをいったん前12世紀あたりまで戻してみよう。「海の民」の襲撃でヒッタイトが滅亡、エジプト新王国も衰退すると、メソポタミアではセム語系のアッシリアが強大化してきた。もともとアッシリアは、初期にはアッシュルを都とする小国で、前15世紀ころにはミタンニ王国に服属していたんだけど、ヒッタイトが滅んだのち、強大な軍事国家になった。アッシリア軍ってこれまでのオリエントの軍事技術を全部集めて、さらに発展させたんだよ。",
        "まずは鉄製武器や戦車を導入したんだけど、これは前からあったよね。で、前9世紀ころにはさらに騎馬隊を組織して機動力に優れた軍隊（ちなみに川を渡るための特殊部隊もいたらしい！）をつくった。野球じゃないけど、機動力って勝つポイントだよ。こうして、シリア・バビロニアからアナトリア、イラン高原を征服すると、さらにパレスチナやエジプトにも進軍したんだね。"
      ],
