      "title": "オリエントは、再び4王国分立へ……",
      "body": [
        "アッシリアが滅亡したとき、オリエントでは4王国が分立していた。そのうちメディアと新バビロニアはアッシリアを滅ぼした国だよ。では、その4王国を順に見ていくことにしよう。",
        "まずは、アナトリア南西部に建てられたインド＝ヨーロッパ語系のリディア王国だ。リディアはイオニア地方に住むギリシア人を勢力下に置きながら地中海への交易活動をおこなったんだ。ギリシア人もリディアと商業上の利益が共通していたから、友好的だった。要するに「両方が儲かればいい！」ってことだね。そして、リディアといえば、世界最古の鋳造貨幣を使用したのもポイントだ。鋳造貨幣って「コイン（硬貨）」のことね。これがギリシアにも伝わって、ギリシア世界にも変化をもたらすんだよ。"
      ],
