        "アケメネス朝は、第3代のダレイオス1世の時代になると、西はアナトリアからエーゲ海北岸まで、南はエジプトまで、そして東はインダス川流域までを支配する広大な「世界帝国」に発展した。そこで、ダレイオス1世は「諸王の王」と名乗って、さまざまな民族を支配するための制度を整えていったよ。",
