      "id": "achaemenid-004",
      "title": "アケメネス朝の全盛期――ダレイオス1世の登場！",
      "body": [
        "ダレイオス1世の一番の功績は、中央集権体制を確立したことだよ。まず、全国を約20州に分けてサトラップと呼ばれる知事を任命、彼らに治安維持や徴税、さらには兵員の募集などを担わせた。ただ、サトラップに任命されたのは地方の有力者も多かったから、彼らが裏切らないように「王の目」「王の耳」と呼ばれる監察官（簡単に言うと王のスパイたちだ）を巡回させて、サトラップの監視や州の情報収集をさせたんだ。さらに、「王の道」と呼ばれる長距離国道を建設して、駅伝制を整備した。今で言えば高速道路だね。特に有名な都スサからアナトリアのサルデスに至る王の道はおよそ2500kmもあるよ。これで都と地方が直接結ばれ、行政面ではいち早く地方の情報を知り、軍事面では反乱や戦争の際に素早く軍を送り、経済面では交易しやすくなって商業が活発化したんだよ。",
        "もう一つ、経済面ではリディアで生まれた貨幣制度を採用して金貨や銀貨を鋳造し、税制も整備した。ダレイオス1世の功績ってかなりすごいでしょ。あとは、ギリシアとの間のペルシア戦争もあるけど、これはギリシアのところで話そう（⇒P.75）。"
      ],
