      "id": "parthia-sasanian-006",
      "title": "ササン朝の成立——今度はイラン系農耕民の国だ",
      "body": [
        "3世紀に入ると、今度はイラン南部（もともとアケメネス朝の本拠地ファールス地方）に現れた<span class=\"source-bold\">アルダシール1世【アルデシール1世】</span>がパルティアを滅ぼして、<span class=\"source-bold\">クテシフォン</span>を都に<span class=\"source-bold\">ササン朝</span>を開いた。ササン朝はアケメネス朝と同じイラン系農耕民の国だから、今度こそ本当にアケメネス朝の復興が目標だよ😲。まず、民族宗教である<span class=\"source-bold\">ゾロアスター教を国教</span>にしてイラン人を統合し、中央集権体制の確立を目指した。アケメネス朝はゾロアスター教を保護しただけで国教にはしていないから注意しよう！"
      ],
