      "id": "indus-001",
      "title": "インドの地形を見てみよう",
      "body": [
        "まずは、インドの重要な地形を確認しよう。インドの北側には<span class=\"source-bold\">ヒマラヤ山脈、スレイマン山脈</span>という山脈があるから、インドに侵入してきた民族はまず<span class=\"source-bold\">カイバル峠</span>を越えてすぐの<span class=\"source-bold\">パンジャーブ地方</span>に定住するよ。それから東西に2本の大河、<span class=\"source-bold\">インダス川とガンジス川</span>がある。真ん中の<span class=\"source-bold\">デカン高原</span>も交通の難所だから、ここが南北の境目だよ。ちなみに北インドを支配した王朝は、ほとんどの場合デカン高原より南は支配できなかったんだ。インドを本当に最南端まで支配したのは、インドを植民地にしたイギリスが最初だよ。だから、厳密に言うとインド全土を統一した王朝はないんだよ。これから見ていく王朝の変遷は、北インドが中心だからね。"
      ],
