        "ただ、前1800年ころになると、インダス文明は突然姿を消してしまう。「いきなり消えるなよ😣」って思ったかもしれないけど、インダス文明滅亡の原因は、はっきりしない。インダス川の氾濫とか、気候の乾燥化とか、交易の衰退とか、森林破壊や塩害による農業の不振とか、いろいろいわれているんだけど、どれも決定打に欠けている。ここは、新しい発見があるまでわからないんだろうなぁ……。"
