      "title": "北方からアーリヤ人が侵入してきた！",
      "body": [
        "<span class=\"source-bold\">インド＝ヨーロッパ語系民族</span>は中央アジアで遊牧や牧畜で生活していたんだけど、前2000年ころから各地に移動を開始したよ。オリエントで出てきたヒッタイトやイラン人と同じグループだ。そして<span class=\"source-bold\">アーリヤ人</span>は、インダス文明の崩壊から約200年後の前1500年ころ、<span class=\"source-bold\">カイバル峠</span>を越えてインド西北部に侵入し、馬と戦車を使って先住民を征服すると、<span class=\"source-bold\">パンジャーブ地方</span>に移住したよ。出たな「馬と戦車」😲。機動力が武器だ。彼らはここで牧畜を中心に農耕もおこなっていたよ。でも、すでにインダス文明が衰退してしまったくらいだから、インダス川流域の農業生産力はあまり高くない……。"
      ],
