      "title": "バラモン教の形成——これがインド思想の原点だ！",
      "body": [
        "もともとインドでは自然を神として崇拝していたんだけど、そのうち、祭壇がつくられ司祭が現れて、少しずつ儀式の形が整えられた。このなかで神々に捧げる賛歌を集めたのが、インド最古の文献『<span class=\"source-bold\">リグ＝ヴェーダ</span>』だ。火の神<span class=\"source-bold\">アグニ</span>や雷の神<span class=\"source-bold\">インドラ</span>などへの賛歌が約1000も集められているよ。なかでもインドラは、理想的な戦士として描かれている。仏教の守護神になった<span class=\"source-bold\">帝釈天</span>は、実はインドラだよ。",
        "そして、このあと前600年ころまでに、讃詠（旋律にのせる歌）の方法をまとめた『<span class=\"source-bold\">サーマ＝ヴェーダ</span>』、祭式の方法や祭詞をまとめた『<span class=\"source-bold\">ヤジュル＝ヴェーダ</span>』、呪語を集めた『<span class=\"source-bold\">アタルヴァ＝ヴェーダ</span>』の三つの「ヴェーダ」が編集された。これらの<span class=\"source-bold\">4大ヴェーダ</span>はバラモン教の根本聖典となったよ。こうして自然を神格化した神々を崇拝する<span class=\"source-bold\">バラモン教</span>が成立し、バラモン階級は儀式を通じて人びとを支配したんだ。実は、この「儀式」が問題になるんだよ。"
      ],
