      "id": "vedic-india-008",
      "title": "バラモン教の形成——これがインド思想の原点だ！",
      "body": [
        "「はぁ？　わけわからん！」って思ったでしょ😅。ただ、この考え方がインド思想の根本だったりする。うーん、困った。入試ではとりあえず用語が書ければ問題はできるけど、ただの暗記じゃつまんないから、ちょっとだけ説明するね。",
        "まずは、「<span class=\"source-bold\">輪廻転生</span>」。まずインド人にとっては「生きること＝苦行」なのね。そして、輪廻っていうのはズバリ「生まれ変わり」。古代のインド人は、輪廻を「人が死ぬと、霊魂は火葬の煙とともに月の世界に昇り、雨となって地中に戻り、食べられることを通して再び生き物の胎内に宿る」って考えた。そして、次の世で何に生まれ変わるかは、<span class=\"source-bold\">業（カルマ）</span>、簡単に言うと「現世での行い」で決まる。行いがよければ上の階級（バラモンやクシャトリヤ）に生まれ変わり、行いが悪ければ下の階級（ヴァイシャやシュードラ）、あるいはもっと下の動物に生まれ変わる。要するに世代を超えた「<span class=\"source-bold\">因果応報</span>」ってことだ。ただし、ここで根本的な問題にぶち当たるよね。いくらよい階級に生まれ変わっても「生きること＝苦行」だ。つまり、輪廻とは「永遠に苦しみが続く」ことなんだよ😣。"
      ],
