      "id": "vedic-india-010",
      "title": "バラモン階級への不満がどんどんたまっていって……",
      "body": [
        "では、入試レベルに戻るよ！　バラモン階級の<span class=\"source-bold\">祭式至上主義</span>に反発して、バラモン階級内部から<span class=\"source-bold\">ウパニシャッド哲学</span>が出てくるのに加えて、この時期になるとクシャトリヤやヴァイシャたちの不満が大きくなったんだ。",
        "まずはクシャトリヤの不満。この時期にガンジス川流域に建てられたアーリヤ人の部族国家は、抗争しながら徐々に大きな国へと成長していったんだけど、戦争で活躍しているのは軍事担当のクシャトリヤだ。それからヴァイシャの不満。ガンジス川流域で農業生産力が向上するにつれて、余ったもの（余剰生産物）を取引する商業や手工業が発展し始めた。そうするとヴァイシャのなかには富を蓄えて豊かになる者が現れた。しかし、どんなに軍隊が強くなったり金持ちになったりしたところで、社会はバラモンに支配されているし、しかもヴァルナ制では、解脱して救われるのはバラモンだけ😡。クシャトリヤやヴァイシャだって救われたいよね！",
        "そして、この両者の不満はどちらもヴァルナという宗教的な身分階級に基づくものだから、これを解決するには新しい宗教をつくるしかない。こうしてインドでは、ヴァルナを否定する新思想が出現したんだね。これが<span class=\"source-bold\">仏教とジャイナ教</span>だ。"
      ],
