      "id": "north-india-003",
      "title": "広大な領域を支配したアショーカ王。支配の秘訣は？",
      "body": [
        "さて、マウリヤ朝はその後もデカン高原の征服を進め、第3代の<span class=\"source-bold\">アショーカ王【阿育王】</span>時代に全盛期を迎えた。彼は北インドの東南部にあった<span class=\"source-bold\">カリンガ国</span>を征服して、最南部を除いた<span class=\"source-bold\">全インド</span>を統一したよ。南端部の国もマウリヤ朝とは友好関係にあったから、もはや征服する必要はなかったしね。",
        "ここで地図を確認！　古代インド史で出てくる四つの王朝は、それぞれの支配領域の特徴がはっきりと違うから確実に区別できる。ということは、入試によく出てくるってことだ。よく見てね！　マウリヤ朝は最南部以外を全部支配しているのが特徴だ。ちなみに、これが古代インド王朝の領域で最大だね。"
      ],
