      "title": "クシャーナ朝のインド支配――カニシカ王が登場！",
      "body": [
        "では、クシャーナ朝のインド支配について見ていこう。クシャーナ朝は2世紀に出現した<span class=\"source-bold\">カニシカ王</span>時代に全盛期を迎えたよ。カニシカ王は都をガンダーラ地方の<span class=\"source-bold\">プルシャプラ</span>に置き、中央アジアからガンジス川中流域にいたる領土を支配した。",
        "彼はアショーカ王と並ぶ仏教の保護者として知られているけど、民族から宗教までバラバラなインドを統治するために、アショーカ王の政策をパクったんだ。だから、すべての宗教に寛大だったなかで、特に仏教を手厚く保護したよ。というか、カニシカ王はゾロアスター教徒……仏教以外の宗教を弾圧したら自爆だよ😅。",
        "おっと本題ね。カニシカ王の仏教保護のもとで、<span class=\"source-bold\">第4回仏典結集</span>がおこなわれたんだけど、このとき保護されたのは<span class=\"source-bold\">大乗仏教</span>だ。これ、アショーカ王の時代とは違うね。というより、アショーカ王の時代には、まだ大乗仏教はなかったからね。"
      ],
