      "id": "north-india-011",
      "title": "大乗仏教って何？　みんなが救われる新しい仏教だ！",
      "body": [
        "大乗仏教を見る前に、もともとの仏教を確認しておこう。仏教はいくつかのグループに分かれていて（部派仏教）、なかでも有力だった<span class=\"source-bold\">上座部仏教</span>は、「出家した個人が修行して、個人の救済（救済＝解脱だ）を目指す」宗教だった。だから、解脱したい人は、仕事もしないでひたすら修行するしかない。",
        "ただ、誰もが出家できるわけじゃないよね？　だって、出家すると仕事ができないから、出家して救われるのは金持ちか、飢え死にを覚悟した人だけ😨。仏教の僧たちは他の宗教を見て、「修行しない人でも救われる方法があるのでは」って思ったんだろう。例えばギリシア人は、困ったことがあると神殿に行ってお祈りして、神託を聞けば救われる。これ日本人に近いね。神社におまいりして、おみくじ引いて帰ってくる、みたいな😅。ほら、出家しないで救われるでしょ。"
      ],
