      "id": "north-india-016",
      "title": "ついにインド人王朝が復活！　英雄チャンドラグプタも復活？",
      "body": [
        "クシャーナ朝が衰退したあとの北インドの混乱を収束したのは、ガンジス川流域から興った<span class=\"source-bold\">グプタ朝</span>だ。グプタ朝は、かつてのマウリヤ朝の故地から出現した<span class=\"source-bold\">チャンドラグプタ1世</span>が、<span class=\"source-bold\">パータリプトラ</span>を都に建てた王朝だ。ほら、インドには「生まれ変わる」っていう輪廻思想があったよね。この王朝って、まさにマウリヤ朝の生まれ変わりだ。彼自身も「俺はチャンドラグプタの跡を継ぐ者だ😎！」って思ってたみたい。だからといってマウリヤ朝と血縁関係はないからね。"
      ],
      "plainBody": [
        "クシャーナ朝が衰退したあとの北インドの混乱を収束したのは、ガンジス川流域から興ったグプタ朝だ。グプタ朝は、かつてのマウリヤ朝の故地から出現したチャンドラグプタ1世が、パータリプトラを都に建てた王朝だ。ほら、インドには「生まれ変わる」っていう輪廻思想があったよね。この王朝って、まさにマウリヤ朝の生まれ変わりだ。彼自身も「俺はチャンドラグプタの跡を継ぐ者だ😎！」って思ってたみたい。だからといってマウリヤ朝と血縁関係はないからね。"
      ],
