      "id": "north-india-024",
      "title": "ハルシャ＝ヴァルダナが登場！　北インドを統一しかけたんだけど……",
      "body": [
        "グプタ朝滅亡後の混乱のなかから現れ、ガンジス川流域の覇者となったのが、<span class=\"source-bold\">ハルシャ＝ヴァルダナ【ハルシャ王】</span>だ。彼の治世を<span class=\"source-bold\">ヴァルダナ朝</span>と呼ぶよ。ハルシャ＝ヴァルダナは、ガンジス河畔の<span class=\"source-bold\">カナウジ</span>を都に定めると、積極的な征服活動をおこない、デカン高原の征服を目指して軍を南下させたんだけど、<span class=\"source-bold\">チャールキヤ【カルキヤ】朝</span>に敗れて、南北統一は実現できなかった。ここで地図を確認しよう！　ヴァルダナ朝の支配領域は、ガンジス川流域とインダス川流域のごく一部だけだ。"
      ],
